export function musicMetadata(musicId: number): MusicMetadata | null {
  const normalized = Number(musicId);
  if (!Number.isFinite(normalized) || normalized < 0) return null;
  return MUSIC_METADATA[String(Math.floor(normalized))] || null;
}

export function isClassicNewMusic(musicId: number, gameCode: string): boolean {
  const metadata = musicMetadata(musicId);
  if (!metadata) return false;
  return String(gameCode || '').toUpperCase() === 'K32'
    ? metadata.firstClassicVersionK32 === 17
    : metadata.firstClassicVersionK33 === 18;
}

